import{_ as s,O as a,o as r,c as i,a as o,i as n,f as l}from"./chunks/framework.fmIt2z2h.js";const y=JSON.parse('{"title":"D.13　亲属、交换、仪式、民族志与文化变迁","description":"","frontmatter":{"title":"D.13　亲属、交换、仪式、民族志与文化变迁","xkChars":667,"xkLessons":{"D.13":{"title":"D.13　亲属、交换、仪式、民族志与文化变迁","lead":"共同参加一场仪式，可以说明共同出席；是否相信同一件事、记忆是否准确、以后是否合作，还需要各自的材料。民族志能补足表格遗漏的经验，也必须交代进入、记录、公开和代表的边界。","explanation":["原文定位：第4721—4736行；原文锚点 section-d-13；短引文：‘仪式存在、生理同调、身份表达、记忆准确和持续合作各有证据单位。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","亲属规则、礼物债务、仪式分类、惯习资本、生态生计和民族志有各自分析单位。亲属称谓不直接等于实际照护网络，非市场交换不表示没有义务，礼物与商品也可能在同一关系里交织。应按交换安排、期待和权力具体判断，而非只看是否使用货币便宣布关系属于纯粹赠予或纯粹市场。","仪式协调、公共身份、私人相信与长期合作可能不同步。成员共同出席可以来自认同，也可出于礼节、角色要求、收入或避免冲突；动作同步也不直接证明内心信念一致。不能由一个可见行为补齐其他不可见结果，更不能借仪式完整举行替代后续合作与分配的检验。","象征解释问实践在具体语境中如何被理解，物质与制度研究追踪资源、劳动、约束和后果。二者可以互相修正：某种资源安排可能改变仪式意义，意义又可能影响行动。但一个细致意义解释不自动证明资源因果，一组投入产出数字也不穷尽参与者的理解。互校不等相互代付。","惯习是长期实践中可能形成的稳定倾向，但不等于完全固定的人格本质。多重社会化、不同领域冲突以及环境变化可能使倾向修订。需要记录实践怎样形成、在哪些条件稳定、何时改变，而不是从一次动作或一个阶层标签推定全部生活都会按同一路径发生。","资本转换依赖特定领域的承认和规则。例如某种技能、头衔或关系能在一个场合换取机会，不意味着到另一场合仍具有同一效力。转换不是无条件能量守恒，也不能在未经说明的统一尺度上把一切资源加总。若原作者主张更强的总体解释，应保留其强承诺再评价，不能先削弱成常识后宣布已经完全兼容。","民族志的进入、信任、记录、公开和代表权不是一次许可的不同名字。获准进入场域不自动获准记录所有私密内容，愿意接受访谈不必等于同意无限公开，研究者熟悉场域也不等于掌握全体成员意愿。每种资格需有相应依据，尤其不能把未接触者或无法安全发言者的缺席当成同意。","厚描的细节能呈现标准调查表遗漏的情境，但观察者在场也可能改变表达。应说明进入路径、谁愿意谈、谁没被接触、谁不能安全说话，以及研究者怎样影响互动。反身性不是用主观一词否定所有材料，而是把材料如何形成写入解释，让读者知道适用范围和遗漏。","文化变化不必只在真实传统与伪造传统之间二选一。原文新媒介节庆例允许技艺继续创造，也允许某些经验消失，两者同时登记。新的表达不必因此为假，延续传统也不证明内部控制和分配毫无问题。谁有权决定如何变化、谁获益、谁承担损失仍须独立讨论。","文化相对主义与共同保护的分歧应进入具体理由，不能靠尊重文化四字取消受影响者保护，也不能凭外部尺度直接宣布所有本地意义无价值。解释一个实践为何对人重要，与是否允许某种伤害，是不同任务；需要保留文化内部的分歧与批评位置。","不能把原作者的强承诺先改写成中性提醒。若原文主张象征、物质条件或资本转换有明确优先序、统一尺度或总体协调作用，应准确呈现并问哪些材料能支持或反驳。局部采用一种有用分析与接受其全部理论是不同决定；兼容必须有边界，不能靠删掉争议获得。","仪式存在、心率等生理同调、身份表达、记忆准确与持续合作分别有证据单位。共享同一事件或底样的多篇文章可分析不同结果，但篇数不等独立验证次数；重复分析不能冒充新抽样。八个入口依次是Mauss和Lévi-Strauss等亲属礼物，Durkheim、van Gennep、Turner的仪式共同感，Geertz与Douglas的象征分类，Bourdieu的惯习场域资本，文化唯物生态生计，民族志厚描参与观察，相对主义与共同保护，以及混合复兴变迁。目录不能替代这些强理论的完整原文。"],"distinctions":[{"leftTitle":"共同出席","leftText":"在同一活动中出现。","rightTitle":"相信记忆合作","rightText":"私人信念、记忆准确及后续行为均需另外材料。"},{"leftTitle":"象征意义解释","leftText":"描述实践在语境中如何被理解。","rightTitle":"物质制度机制","rightText":"追踪资源约束与后果，不能由意义解释代替。"},{"leftTitle":"场域进入与信任","leftText":"获得某种接触及交流关系。","rightTitle":"记录公开代表权","rightText":"每一用途需要自己的依据与边界。"},{"leftTitle":"文化继续创造","leftText":"旧实践通过新条件产生新的表达。","rightTitle":"无损延续","rightText":"新创造可同时有损失与内部争议。"},{"leftTitle":"多篇研究文章","leftText":"可能呈现不同结果或分析。","rightTitle":"多次独立验证","rightText":"需核事件样本与信息依赖，不能直接按篇数计。"}],"boundaries":["不将熟悉场域等同全体成员授权或代表，不公开未经许可的民族志材料。","共同出席、生理同调、身份表达、记忆和合作分开，不靠一项补齐其他项。","不把文化变迁自动写成伪造，也不将传统延续当作内部无控制无损害的证明。","不抹去原作者的强理论承诺再制造兼容。","本讲未参与田野或危险仪式，所有日常场景为教学构造；原研究未重分析。"],"questions":["厚描为什么既有价值又要交代观察者影响？","资本为何不能无条件转换？","共同底样的三篇文章如何计数？","局部采用理论为何不等于整体兼容？"],"diagramPath":"/reading-assets/S-D-13/figures/section-d-13.png","caseLinks":[{"title":"真实原始研究：火行仪式中的心率记录","href":"https://liology.wordpress.com/wp-content/uploads/2011/05/konvalinka-synchronized-arousal.pdf"}],"caseNotes":[{"title":"真实原始研究：火行仪式中的心率记录","text":"Konvalinka等2011年论文在西班牙San Pedro Manrique记录12名火行者、9名相关观众和17名无关观众，合计38人的心率；Results首段与方法说明以5秒间隔平均记录，分析仪式与基线时段。论文讨论共享唤醒，并在Early Edition第5页明确其是驱动机制还是涌现性质仍不清楚。这类心率证据不应直接填成所有参与者长期合作或记忆准确。","sourceLabel":"Konvalinka et al.，2011，doi:10.1073/pnas.1016955108，公开原论文Early Edition副本","sourceUrl":"https://liology.wordpress.com/wp-content/uploads/2011/05/konvalinka-synchronized-arousal.pdf","sourceLocator":"PNAS Early Edition第2页Results首段；第5页Discussion中It remains unclear段；Materials and Methods的Participants、Materials and Procedure首两段","boundary":"按所读原文文字核方法与作者不确定性，不重估RQA/CRQA，不引图中读数，不将观察研究称为随机试验；PDF截图接口失败，未据图像作判断。","href":"https://liology.wordpress.com/wp-content/uploads/2011/05/konvalinka-synchronized-arousal.pdf"}],"sourceRefs":[{"section":"D.13","start_line":4721,"end_line":4736,"startLine":4721,"endLine":4736}],"outputId":"section-d-13","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["固定亲属交换仪式象征资源等分析单位，避免一个可见行为补齐全部关系结果。","将语境意义与物质制度后果互校，保留惯习变化及资本转换的领域条件。","分别核进入信任记录公开代表权限，写明观察者影响、未接触者与不安全发言。","同时记录文化继续创造与具体损失，讨论内部控制、分配及共同保护。","原作者强承诺按原文保留；逐结果追踪证据底样，不用论文篇数虚增独立验证。"],"teachingExamples":[{"title":"原文教学例展开：新媒介的保存与失落","text":"假想节庆引入视频传播后，外地参与和部分收入增加，某项技艺得到学习传承，但原来的面对面相遇经验减少。可分别确认新创造、技艺延续和具体损失，不能只因媒介新就称伪造，也不能因保存技艺便宣布收入分配和决策权公平。","assumptions":"沿原文展开，无真实节庆调查。","boundary":"每项现实效果均需自己的资料，例中条件不能用作任何文化政策的现成证明。"},{"title":"教学构造：到场并不等于信念一致","text":"假想三人同场参与仪式：一人认同其意义，一人履行家庭礼节，一人为了工作要求。到场记录相同而动机不同；若研究后续合作，需要另外观察，不能从座位表直接填入共同信仰和稳定团结。","assumptions":"动机由教学设定给出，真实动机不能直接读心。","boundary":"不否认到场的有限协调或身份意义，只拒绝越界推断。"},{"title":"教学构造：两个领域的资本转换","text":"假想某人有被行业A认可的技能证书，在行业B却不满足资格要求。证书仍真实存在，但它能否转成机会取决于B的规则与承认。不能把证书数量当所有领域可等价转换的能量。","assumptions":"行业证书与规则均虚构。","boundary":"不裁定真实职业资格或工作机会，也不概括Bourdieu全部理论。"},{"title":"教学构造：三篇文章仍来自一次事件","text":"假想同一场仪式、同一批30名参与者的数据分别用于三篇生理、访谈和记忆文章。结果类型变多可增加理解，但独立事件仍为1、不重复计数的参与者仍为30，不能写成90名或三次独立复现。","assumptions":"数据规模与三篇文章均作者构造，不指控任何真实研究重复发表。","boundary":"同底样不等毫无新增价值；只须如实标依赖与结果单位。"}],"counterexamples":[{"identity":"source_counterexample","text":"大家共同出席，所以他们一定内心认同、记得准确并会长期合作。","effect":"可见共同出席不能代填私人信念、记忆与行为结果。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"新媒体改变传统，因此新表达必然是假的。","effect":"变化可是真实继续创造，同时仍需登记损失和分配问题。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"先把某理论的优先序改成各因素都重要，再说各学派完全兼容。","effect":"这丢掉原作者强承诺，应按原文保留后评价有限采用。","sourceIds":["theory"]}],"questionAnswers":[{"question":"厚描为什么既有价值又要交代观察者影响？","answer":"它可发现表格遗漏的经验，但材料形成受进入和互动影响，边界应透明而非全盘否定。","basis":"本节原文及上述公开推导"},{"question":"资本为何不能无条件转换？","answer":"它的有效性取决于领域承认和规则，跨领域可能失效或需其他条件。","basis":"本节原文及上述公开推导"},{"question":"共同底样的三篇文章如何计数？","answer":"分别登记三个分析或结果，同时保留同一底样依赖，不写三次独立复现。","basis":"本节原文及上述公开推导"},{"question":"局部采用理论为何不等于整体兼容？","answer":"原理论可能有更强的优先序和统一解释承诺，局部工具不能替全部论证结案。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-13/figures/section-d-13.png","alt":"亲属交换仪式，各有分析单位，礼物也可有义务；意义与资源后果互校，不互相代付；进入／信任／记录，公开／代表，逐项核依据；文化继续创造，可以同时有损失，控制分配另查；出席／生理同调，身份／记忆／合作，各有证据单位；保留理论强承诺，同底样多篇，不算多次独立验证。作者依D.13绘制；教学例非真实田野。图未复制原论文图像或表示原始数据。","caption":"作者依D.13绘制；教学例非真实田野。图未复制原论文图像或表示原始数据。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换材料类型与样本依赖，显示出席、生理、信念、记忆和合作需要哪些独立支持。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"原始方法限定生理证据单位并保留作者机制未决；不借仪式研究跳到私人信念、准确记忆和长期合作。"},"openQuestions":["未取得13.01—13.08全部理论原稿，不以目录替代强承诺完整评估。","案例仅核明确列出的PDF方法讨论文字；原始心率数据、补充材料和独立复现未复核，PDF截图未取得。"],"taskId":"S-D-13","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4721—4736行；每节精确范围见sourceRefs","claim_support":["D.13：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"konvalinka2011","title":"Synchronized arousal between performers and related spectators in a fire-walking ritual","url":"https://liology.wordpress.com/wp-content/uploads/2011/05/konvalinka-synchronized-arousal.pdf","source_type":"primary","version_or_date":"2011；PNAS DOI10.1073/pnas.1016955108，Early Edition六页版","locator":"Early Edition p2 Results首段；p5 Discussion的It remains unclear段；p5 Materials and Methods中Participants与Materials and Procedure首两段","claim_support":["12+9+17=38的心率记录分组、5秒平均、基线与仪式时段；作者机制/涌现性质未决"],"limits":["仅读指定方法讨论文字；未重估数据或图表，PDF截图接口失败；不据心率代判长期合作和记忆。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-13/lecture.md","sourcesPath":"/reading-assets/S-D-13/sources.json","sourceSlicePath":"/reading-assets/S-D-13/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-13/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-13.md","filePath":"theory/appendix-d/d-13.md"}'),d={name:"theory/appendix-d/d-13.md"};function c(u,e,p,h,m,f){const t=a("SectionLesson");return r(),i("div",null,[e[0]||(e[0]=o('<div class="theory-source"><h1 id="section-d-13" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.13</span><span class="xk-num__gap">　</span></span>亲属、交换、仪式、民族志与文化变迁 <a class="header-anchor" href="#section-d-13" aria-label="Permalink to &quot;D.13　亲属、交换、仪式、民族志与文化变迁 {#section-d-13}&quot;">​</a></h1><p>正文连接：§2.5—2.7；§7.5；§9.7；§10；§16.6。研究入口：13.01—13.08。</p><p>亲属规则、礼物与债务、仪式与分类、惯习与资本、生态生计和民族志分别保留自己的分析单位。非市场交换不等没有义务，礼物与商品也可以在同一关系中交织。仪式协调、公共身份、私人相信和长期合作可能不同步，不能由共同出席补齐所有结果。</p><p>象征解释要说明一个实践在语境中怎样被理解；物质与制度研究则追踪资源、劳动、约束和后果。两者可以互校，却不能相互代付。惯习可以在长期实践中形成稳定倾向，也可能因多重社会化和环境变化而修订；资本转换需要特定领域中的承认与规则，不是无条件能量转移。</p><p>民族志的进入、信任、记录、公开及代表权须分别取得依据。厚描的细节可以使研究者看见调查表遗漏的经验，但熟悉一个场域不等于掌握全体成员意愿。观察者在场如何改变表达、谁未被接触、谁不能安全说话，应保留为解释的一部分，而非用“主观”二字将材料全部排除。</p><p>教学例：一种节庆引入新媒介后，参与方式和收入发生改变，某些技艺得以保存，另一些经验不再出现。它可以是真实的文化继续创造，同时存在明确损失；“新创造”不等于伪造传统，“保留传统”也不证明没有内部控制与分配问题。文化相对主义与共同保护的分歧，应进入具体论证。</p><p>原作者的强承诺必须按原文保留。采用象征解释、物质条件或资本转换中的局部分析，不应先把其优先序、统一尺度或总体协调主张全部改成中性提醒，再宣布各传统相容。仪式存在、生理同调、身份表达、记忆准确和持续合作各有证据单位；共同仪式与重复底样不能被分篇数量改写成多次独立验证。</p><p>专题定位：13.01 亲属、交换与礼物：Mauss、Lévi-Strauss 等；13.02 仪式、阈限与共同感：Durkheim、van Gennep、Victor Turner；13.03 象征、分类与文化解释：Geertz、Douglas；13.04 惯习、场域与资本：Bourdieu；13.05 文化唯物主义、生态与生计；13.06 民族志、厚描与参与观察；13.07 文化相对主义与共同保护；13.08 文化变迁、混合与复兴。</p></div>',1)),n(t,{section:"D.13"}),e[1]||(e[1]=l("div",{class:"theory-source"},null,-1))])}const g=s(d,[["render",c]]);export{y as __pageData,g as default};
